  subcategories = [
    { id: 1, name: 'Smartphones', parentId: 1, children: [] },
    { id: 2, name: 'Laptops', parentId: 1, children: [] },
    // Add more subcategories as needed
  ];

  selectedSubcategory?: any;

  onSelect(subcategory: any) {
    this.selectedSubcategory = subcategory;
  }
